function evaluateEligibility(profile3, drive) {
  const reasons = [];
  if (!profile3) {
    return {
      eligible: false,
      reasons: ["Student profile not registered or found"]
    };
  }
  if (!profile3.branch || !drive.eligibleBranches.includes(profile3.branch)) {
    reasons.push(
      `Branch "${profile3.branch ?? "Unknown"}" is not eligible. Eligible branches: ${drive.eligibleBranches.join(", ")}`
    );
  }
  if (profile3.cgpa < drive.minCgpa) {
    reasons.push(
      `CGPA (${profile3.cgpa}) is below minimum requirement (${drive.minCgpa})`
    );
  }
  if (profile3.activeBacklogs > drive.maxActiveBacklogs) {
    reasons.push(
      `Active backlogs (${profile3.activeBacklogs}) exceed maximum allowed (${drive.maxActiveBacklogs})`
    );
  }
  const status = (profile3.placementStatus || "UNPLACED").toUpperCase();
  const placedOffers = (profile3.placedCategories || []).map((c) => String(c).toUpperCase());
  const driveCategory = (drive.packageCategory || "GENERAL").toUpperCase();
  const isDreamPlaced = status === "DREAM" || placedOffers.includes("DREAM");
  const isGeneralPlaced = status === "GENERAL" || placedOffers.includes("GENERAL");
  const isInternshipPlaced = status === "INTERNSHIP" || placedOffers.includes("INTERNSHIP");
  if (isDreamPlaced) {
    reasons.push(
      "Students placed in a Dream category offer (\u2265 7 LPA) have achieved maximum placement tier and cannot apply for further drives"
    );
  } else {
    if (isGeneralPlaced && driveCategory === "GENERAL") {
      reasons.push(
        "Students placed in a General category offer cannot apply for another General category drive"
      );
    }
    if (isInternshipPlaced && driveCategory === "INTERNSHIP") {
      reasons.push(
        "Students who have secured an Internship offer cannot apply for other Internship drives"
      );
    }
  }
  return {
    eligible: reasons.length === 0,
    reasons
  };
}
