          java: `import java.util.*;
class Solution {
    public long solution(int[] tasks, int k) {
        if (tasks.length == 0) return 0;
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int i = 0; i < k; i++) pq.add(0L);
        for (int t : tasks) {
            long earliest = pq.poll();
            pq.add(earliest + t);
        }
        long max = 0;
        while (!pq.isEmpty()) max = Math.max(max, pq.poll());
        return max;
    }
}`,
